components.css:
.ds-button-primary{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius);background:var(--primary);color:var(--primary-foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-primary:hover{background:color-mix(in oklch,var(--primary) 80%,transparent)}
.ds-button-primary:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-primary:active{transform:translateY(1px)}
.ds-button-primary:disabled{opacity:.5;cursor:not-allowed}

.ds-button-outline{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-outline:hover{background:var(--muted);color:var(--foreground)}
.ds-button-outline:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-outline:active{transform:translateY(1px)}
.ds-button-outline:disabled{opacity:.5;cursor:not-allowed}
:host-context(.dark) .ds-button-outline{border-color:var(--input);background:color-mix(in oklch,var(--input) 30%,transparent)}
:host-context(.dark) .ds-button-outline:hover{background:color-mix(in oklch,var(--input) 50%,transparent)}

.ds-button-ghost{display:inline-flex;align-items:center;justify-content:center;height:32px;padding:0 10px;border:1px solid transparent;border-radius:var(--radius);background:transparent;color:var(--foreground);font:500 14px/1 var(--font-sans);white-space:nowrap;transition:all 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-button-ghost:hover{background:var(--muted);color:var(--foreground)}
.ds-button-ghost:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
.ds-button-ghost:active{transform:translateY(1px)}
.ds-button-ghost:disabled{opacity:.5;cursor:not-allowed}
:host-context(.dark) .ds-button-ghost:hover{background:color-mix(in oklch,var(--muted) 50%,transparent)}

.ds-search-field{display:block;width:100%;height:34px;padding:0 43px 0 32px;border:1px solid transparent;border-radius:7px;background:var(--muted);color:var(--foreground);font:400 12px var(--font-sans);transition:color 150ms cubic-bezier(0.4,0,0.2,1),background-color 150ms cubic-bezier(0.4,0,0.2,1)}
.ds-search-field::placeholder{color:var(--muted-foreground)}
.ds-search-field:focus-visible{outline:2px solid var(--foreground);outline-offset:3px;border-color:var(--ring);box-shadow:0 0 0 3px color-mix(in oklch,var(--ring) 50%,transparent)}
:host-context(.dark) .ds-search-field{background:color-mix(in oklch,var(--input) 30%,transparent)}
@media(max-width:767px){.ds-search-field{height:40px;font-size:14px}}

.ds-tag-chip{display:inline-flex;align-items:center;gap:5px;padding:3px 7px;border-radius:4px;background:var(--muted);color:var(--muted-foreground);font:400 10px var(--font-sans)}
.ds-tag-chip button{padding:1px;border:0;border-radius:2px;background:transparent;color:inherit}
.ds-tag-chip button:hover{background:color-mix(in oklch,var(--foreground) 8%,transparent)}
.ds-tag-chip button:focus-visible{outline:2px solid var(--foreground);outline-offset:3px}

.ds-writing-surface{max-width:800px;margin:0 auto;padding:58px 52px 100px;color:var(--foreground);font-family:var(--font-sans)}
.ds-writing-surface time{display:block;margin-bottom:18px;color:var(--muted-foreground);font-size:11px}
.ds-note-title{display:block;width:100%;margin:0;padding:0;overflow:hidden;resize:none;border:0;border-radius:0;background:transparent;color:var(--foreground);font:550 32px/1.4 var(--font-sans);letter-spacing:-.035em}
.ds-note-title:focus-visible{outline:2px solid var(--ring);outline-offset:6px;border-radius:4px}
.ds-note-body{font:400 16px/1.7 var(--font-sans)}
.ds-note-body p{margin:0 0 12px}
.ds-note-body pre{overflow:auto;padding:20px 24px;border-radius:8px;background:#171717;color:#ededed;font:13px/1.7 var(--font-mono)}
@media(max-width:767px){.ds-writing-surface{padding:32px 26px 80px}.ds-note-title{font-size:29px}}
